import { beforeEach, describe, expect, it, vi } from "vitest";
import { createSession } from "@/auth/session";
import type { TransferRow, TransfersView } from "@/domain/ledger/read";

// Generated by /ship coverage audit.
// Value: protects=the Transfers page shows a Retry banner (keeping ?to=) when suggestions fail to load, and its empty states;
// fails_when=the load try/catch, the retry href or the "nothing to move" heading regresses; why_new=no test drives a load failure;
// seam=none; no_claim=real Mongo failures (the read adapter and DB handle are mocked; markup checked as React props, not rendered HTML)

let token = "";
vi.mock("next/headers", () => ({ cookies: async () => ({ get: () => ({ value: token }) }) }));
vi.mock("@/lib/db", () => ({ getDb: async () => ({}) }));
const list = vi.fn<(db: unknown, opts: { to?: string }) => Promise<TransfersView>>();
vi.mock("@/domain/ledger/read", () => ({ listTransferSuggestions: (db: unknown, opts: { to?: string }) => list(db, opts), transfersInTransit: async () => [] }));

const { default: TransfersPage } = await import("@/app/(manager)/transfers/page");
// Component element types (e.g. next/link) are circular objects; keep only props and host tag names.
const render = async (to?: string) =>
  JSON.stringify((await TransfersPage({ searchParams: Promise.resolve(to ? { to } : {}) })).props, (k, v) => (k === "type" && typeof v !== "string" ? undefined : v));
const view = (over: Partial<TransfersView> = {}): TransfersView => ({
  suggestions: [],
  total: 0,
  branches: [{ _id: "BR-A", name: "Alpha" }, { _id: "BR-B", name: "Bravo" }],
  blocked: [],
  ...over,
});

beforeEach(() => {
  token = createSession("manager").token;
  list.mockReset();
});

describe("transfers page", () => {
  it("shows a Retry banner when suggestions can't be loaded, keeping the branch filter", async () => {
    list.mockRejectedValue(new Error("db down"));
    const filtered = await render("BR-B");
    expect(filtered).toContain("Couldn't load suggestions");
    expect(filtered).toContain('"href":"/transfers?to=BR-B"');
    expect(filtered).toContain("Retry");
    expect(await render()).toContain('"href":"/transfers"');
  });

  it("with nothing to move says so, and names the receiving branch when filtered", async () => {
    list.mockResolvedValue(view());
    const all = await render();
    expect(all).toContain("nothing to move");
    expect(all).toContain("No branch is both over its cover and able to help one below its reorder point.");
    expect(list).toHaveBeenLastCalledWith(expect.anything(), { to: undefined });
    const into = await render("BR-B");
    expect(into).toContain("No transfers into Bravo right now.");
    expect(list).toHaveBeenLastCalledWith(expect.anything(), { to: "BR-B" });
  });

  it("counts every suggestion in the heading and says when the list is cut to the top ones", async () => {
    list.mockResolvedValue(view({ suggestions: [{} as TransferRow, {} as TransferRow], total: 120 }));
    const page = await render();
    expect(page).toContain("120 suggestions");
    expect(page).toContain("Showing the top ");
    expect(page).toMatch(/"Showing the top ",2," of ",120/);
    list.mockResolvedValue(view({ suggestions: [{} as TransferRow], total: 1 }));
    expect(await render()).not.toContain("Showing the top");
  });
});
